CREATE COLUMN TABLE "TEST_AP"."@QC_UDCODE" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_Active" NVARCHAR(1) DEFAULT 'Y', "U_StockBatch_Status" NVARCHAR(100), "U_Remarks" NVARCHAR(50), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KQC_UDCODE_NAME" ON "TEST_AP"."@QC_UDCODE" ( "Name" ASC )